exports.readStylesXml = readStylesXml;
exports.Styles = Styles;
exports.defaultStyles = new Styles({}, {}, {}, {}, null, null);

function Styles(paragraphStyles, characterStyles, tableStyles, numberingStyles, defaultAlignment, defaultLineSpacing) {
    function resolveParagraphProp(styleId, propName, visited) {
        if (!styleId) return null;
        visited = visited || {};
        if (visited[styleId]) return null;
        visited[styleId] = true;
        var s = paragraphStyles[styleId];
        if (!s) return null;
        if (s[propName]) return s[propName];
        if (s.basedOn) return resolveParagraphProp(s.basedOn, propName, visited);
        return null;
    }

    return {
        defaultAlignment: defaultAlignment || null,
        defaultLineSpacing: defaultLineSpacing || null,
        findParagraphStyleById: function(styleId) {
            var s = paragraphStyles[styleId];
            if (!s) return null;
            return {
                type: s.type,
                styleId: s.styleId,
                name: s.name,
                basedOn: s.basedOn,
                alignment: s.alignment || resolveParagraphProp(s.basedOn, 'alignment'),
                lineSpacingRaw: s.lineSpacingRaw || resolveParagraphProp(s.basedOn, 'lineSpacingRaw')
            };
        },
        findCharacterStyleById: function(styleId) {
            return characterStyles[styleId];
        },
        findTableStyleById: function(styleId) {
            return tableStyles[styleId];
        },
        findNumberingStyleById: function(styleId) {
            return numberingStyles[styleId];
        }
    };
}

Styles.EMPTY = new Styles({}, {}, {}, {}, null, null);

function readStylesXml(root) {
    var paragraphStyles = Object.create(null);
    var characterStyles = Object.create(null);
    var tableStyles = Object.create(null);
    var numberingStyles = Object.create(null);

    var docDefaults = root.firstOrEmpty("w:docDefaults");
    var pPrDefault = docDefaults.firstOrEmpty("w:pPrDefault").firstOrEmpty("w:pPr");
    var defaultAlignment = pPrDefault.firstOrEmpty("w:jc").attributes["w:val"] || null;
    var defaultLineSpacing = pPrDefault.firstOrEmpty("w:spacing").attributes["w:line"] || null;

    root.getElementsByTagName("w:style").forEach(function(styleElement) {
        var style = readStyleElement(styleElement);
        var styleSet;

        switch (style.type) {
        case "paragraph":
            styleSet = paragraphStyles;
            break;

        case "character":
            styleSet = characterStyles;
            break;

        case "table":
            styleSet = tableStyles;
            break;

        case "numbering":
            styleSet = numberingStyles;
            break;
        }

        if (styleSet && styleSet[style.styleId] === undefined) {
            styleSet[style.styleId] = style;
        }
    });

    return new Styles(paragraphStyles, characterStyles, tableStyles, numberingStyles, defaultAlignment, defaultLineSpacing);
}

function readStyleElement(styleElement) {
    var type = styleElement.attributes["w:type"];

    if (type === "numbering") {
        return readNumberingStyleElement(type, styleElement);
    } else {
        var styleId = readStyleId(styleElement);
        var name = styleName(styleElement);
        var basedOn = styleElement.firstOrEmpty("w:basedOn").attributes["w:val"] || null;
        var pPr = styleElement.firstOrEmpty("w:pPr");
        var jc = pPr.firstOrEmpty("w:jc").attributes["w:val"] || null;
        var spacing = pPr.firstOrEmpty("w:spacing").attributes["w:line"] || null;
        return {
            type: type,
            styleId: styleId,
            name: name,
            basedOn: basedOn,
            alignment: jc,
            lineSpacingRaw: spacing
        };
    }
}

function styleName(styleElement) {
    var nameElement = styleElement.first("w:name");
    return nameElement ? nameElement.attributes["w:val"] : null;
}

function readNumberingStyleElement(type, styleElement) {
    var styleId = readStyleId(styleElement);

    var numId = styleElement
        .firstOrEmpty("w:pPr")
        .firstOrEmpty("w:numPr")
        .firstOrEmpty("w:numId")
        .attributes["w:val"];

    return {type: type, numId: numId, styleId: styleId};
}

function readStyleId(styleElement) {
    return styleElement.attributes["w:styleId"];
}
